import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Regimi di sconto","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbcc.md","filePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbcc.md"}`),a={name:`lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbcc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="regimi-di-sconto" tabindex="-1">Regimi di sconto <a class="header-anchor" href="#regimi-di-sconto" aria-label="Permalink to “Regimi di sconto”">​</a></h1><p>Per stabilire il compenso per chi anticipa un pagamento (sconto) intanto bisogna stabilire un tasso (che chiameremo tasso di sconto).</p><p>Inoltre, sono possibili vari metodi per calcolare lo sconto.</p><p>Per capire bene questi metodi pensiamo allo sconto come ad un prestito: se io pago oggi la somma scontata è come se facessi un prestito tale che dopo il periodo di utilizzo mi restituisca il capitale da pagare.</p><p>Posso cioè paragonare la somma scontata ad un capitale che impiegato un certo tempo, fino alla scadenza, mi restituisca come montante il valore nominale.</p><p>Quindi lo sconto corrisponde all&#39;interesse su tale prestito.</p><blockquote><p>Se guardi la retta dei tempi il concetto ti sarà ancora più chiaro pensando a <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> come alla somma scontata ed a <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>M</mi><mi>t</mi></msub></mrow><annotation encoding="application/x-tex">M_t</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> come al valore nominale.</p></blockquote><p>Quindi avremo subito:</p><ul><li>Se penso alla somma scontata come ad un prestito fatto ad interesse semplice avremo il regime dello <strong>sconto razionale</strong>, utilizzato di solito per operazioni a breve scadenza.</li><li>Se penso alla somma scontata come ad un prestito fatto ad interesse composto avremo il regime dello <strong>sconto composto</strong>, utilizzato di solito per operazioni a lunga scadenza.</li><li>Molto usato poi è lo <strong>sconto commerciale</strong>, per la sua semplicità: lo sconto è direttamente proporzionale al valore nominale, al tasso ed al tempo; lo considereremo nella prossima pagina.</li></ul>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};